CREATE TABLE "PublishingConnection" (id TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE CASCADE,provider TEXT NOT NULL,platform TEXT NOT NULL,channel TEXT NOT NULL,"tokenCipher" TEXT NOT NULL,"hookCipher" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE UNIQUE INDEX "PublishingConnection_ownerId_provider_channel_key" ON "PublishingConnection"("ownerId",provider,channel);
CREATE TABLE "PublicationRequest" (id TEXT PRIMARY KEY,"submitKey" TEXT NOT NULL UNIQUE,"cancelKey" TEXT NOT NULL UNIQUE,"connectionId" TEXT NOT NULL REFERENCES "PublishingConnection"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"projectId" TEXT NOT NULL,revision INT NOT NULL,"itemId" TEXT NOT NULL,"itemVersion" INT NOT NULL,state TEXT NOT NULL DEFAULT 'PREPARED' CHECK (state IN ('PREPARED','SENDING','SUBMITTED','CANCELLING','CANCELLED','PUBLISHED','FAILED','UNKNOWN')),reason TEXT,"remoteId" TEXT,"networkReceipt" TEXT,FOREIGN KEY ("projectId",revision) REFERENCES "CreativeRevision"("projectId",version) ON DELETE RESTRICT ON UPDATE CASCADE,UNIQUE("itemId","itemVersion","connectionId"),UNIQUE("connectionId","remoteId"));
CREATE TABLE "PublicationEvent" ("requestId" TEXT NOT NULL REFERENCES "PublicationRequest"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"eventId" TEXT NOT NULL,digest TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY("requestId","eventId"));

-- A calendar edit must not bypass a pending, ambiguous or confirmed remote effect.
CREATE UNIQUE INDEX "publication_one_effect" ON "PublicationRequest"("itemId","connectionId") WHERE state IN ('SENDING','SUBMITTED','CANCELLING','PUBLISHED','UNKNOWN');
